<?php
declare(strict_types=1);$token=preg_replace('/[^a-f0-9]/','',(string)($_GET['token']??''));$test=(string)($_GET['data_mode']??'')==='test';if(strlen($token)!==64){http_response_code(404);exit('Projector link not found.');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BDC Dance Cup Live Projection</title><style>:root{--bg:#08111f;--bg2:#5b1833;--text:#fff;--muted:#d9c9d1;--card:rgba(255,255,255,.09);--line:rgba(255,255,255,.2);--accent:#e5bd59}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;font-family:Inter,Arial,sans-serif;background:var(--bg);color:var(--text)}body[data-theme=obsidian_gold]{--bg:#050608;--bg2:#44371e;--accent:#d8b761}body[data-theme=ivory_wine]{--bg:#fffaf0;--bg2:#f1e2e6;--text:#341525;--muted:#735866;--card:rgba(255,255,255,.75);--line:#d7c4ca;--accent:#8b2948}body[data-theme=pearl_navy]{--bg:#f8fbff;--bg2:#dce8f6;--text:#10213d;--muted:#4c6380;--card:rgba(255,255,255,.78);--line:#b9cbe0;--accent:#215d9c}body{background:radial-gradient(circle at 50% 0,var(--bg2),var(--bg) 65%)}#app{width:100vw;height:100vh;padding:clamp(18px,2vw,42px);display:flex;flex-direction:column}.brand{display:flex;align-items:center;justify-content:space-between;gap:2vw}.logo{width:clamp(58px,6vw,108px);aspect-ratio:1;background:#fff;border-radius:18px;padding:8px;box-shadow:0 10px 30px #0003}.logo img{width:100%;height:100%;object-fit:contain}.event{text-align:center;flex:1}.event h1{font-size:clamp(20px,2.2vw,46px);margin:0}.event p{font-size:clamp(12px,1vw,20px);color:var(--muted);margin:.3em}.screen{flex:1;min-height:0;display:grid;place-items:center;padding-top:2vh}.holding{text-align:center}.holding h2{font-size:clamp(54px,8vw,160px);margin:0}.holding p{font-size:clamp(20px,2.2vw,46px);color:var(--muted)}.contestant{text-align:center}.contestant .number{font-size:clamp(150px,28vw,520px);font-weight:900;line-height:.82;color:var(--accent);text-shadow:0 18px 55px #0004}.contestant h2{font-size:clamp(30px,4vw,82px);margin:.2em}.grid{width:100%;height:100%;display:grid;grid-template-columns:repeat(auto-fit,minmax(min(24vw,260px),1fr));gap:clamp(10px,1.2vw,22px);align-content:center}.card{background:var(--card);border:1px solid var(--line);border-radius:clamp(14px,1.5vw,28px);padding:clamp(14px,1.5vw,28px);display:grid;place-items:center;text-align:center;box-shadow:0 15px 38px #0002}.card strong{font-size:clamp(18px,1.7vw,34px)}.card small{color:var(--muted);font-size:clamp(12px,1vw,19px)}.score-board{width:100%;max-height:100%;overflow:hidden}.row{display:grid;grid-template-columns:100px 1fr 180px;gap:16px;align-items:center;padding:clamp(8px,1vh,16px) 20px;border-bottom:1px solid var(--line);font-size:clamp(16px,1.5vw,30px)}.row .place{font-weight:900;color:var(--accent)}.row .score{text-align:right;font-weight:800}.progress-board{grid-template-columns:1fr 1fr}.submitted{border-color:#35c978}.pending{border-color:#e5bd59}@media(max-aspect-ratio:1/1){.progress-board{grid-template-columns:1fr}.row{grid-template-columns:70px 1fr 100px}}</style></head><body><main id="app"><header class="brand"><div class="logo"><img src="../../public/assets/img/bdc-logo.png" alt="BDC"></div><div class="event"><h1 id="eventName">BDC Dance Cup</h1><p id="categoryName">Live Projection</p></div><div style="width:clamp(58px,6vw,108px)"></div></header><section class="screen" id="screen"></section></main><script>(()=>{const token=<?=json_encode($token)?>,test=<?=$test?'true':'false'?>,screen=document.getElementById('screen'),eventName=document.getElementById('eventName'),categoryName=document.getElementById('categoryName');let version=-1,cycle={index:0,phase:'contestant',next:0};const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function header(d){document.body.dataset.theme=d.state.theme;eventName.textContent=d.state.event_name;categoryName.textContent=d.state.category_name+' · '+String(d.state.round_name).toUpperCase()}function holding(d){screen.innerHTML='<div class="holding"><h2>'+esc(d.state.holding_title)+'</h2><p>'+esc(d.state.holding_message)+'</p></div>'}function contestant(e){screen.innerHTML='<div class="contestant"><div class="number">'+esc(e?.contestant_number??'—')+'</div><h2>'+esc(e?.display_name??'Contestant')+'</h2></div>'}function render(d){header(d);const type=d.state.screen_type;if(type==='holding')return holding(d);if(type==='contestant')return contestant(d.active_entry);if(type==='contestants'){screen.innerHTML='<div class="grid">'+d.entries.map(e=>'<div class="card"><strong>Contestant '+esc(e.contestant_number)+'</strong><small>'+esc(e.display_name)+'</small></div>').join('')+'</div>';return}if(type==='judges'){screen.innerHTML='<div class="grid">'+d.judges.map(j=>'<div class="card"><strong>'+esc(j.judge_name)+(Number(j.is_chief)?' ★':'')+'</strong><small>J'+esc(j.judge_order)+' · '+esc(j.status.replaceAll('_',' '))+'</small></div>').join('')+'</div>';return}if(type==='scoring'){const done=d.judges.filter(j=>j.status==='submitted'),pending=d.judges.filter(j=>j.status!=='submitted');screen.innerHTML='<div class="grid progress-board"><div class="card submitted"><strong>Completed · '+done.length+'</strong><small>'+esc(done.map(j=>j.judge_name).join(' · ')||'Waiting for submissions')+'</small></div><div class="card pending"><strong>Pending · '+pending.length+'</strong><small>'+esc(pending.map(j=>j.judge_name).join(' · ')||'All judges completed')+'</small></div></div>';return}const rows=(type==='podium'?d.results.slice(0,3):d.results);screen.innerHTML='<div class="score-board">'+rows.map(r=>'<div class="row"><span class="place">'+esc(r.placement)+'</span><span><strong>Contestant '+esc(r.contestant_number)+'</strong> · '+esc(r.display_name)+'</span><span class="score">'+Number(r.total_score).toLocaleString(undefined,{maximumFractionDigits:2})+'</span></div>').join('')+'</div>'}async function poll(){try{const r=await fetch('projection-feed.php?token='+encodeURIComponent(token)+(test?'&data_mode=test':''),{cache:'no-store'}),d=await r.json();if(!d.ok)return;if(Number(d.state.state_version)!==version){version=Number(d.state.state_version);cycle={index:Math.max(0,d.entries.findIndex(e=>Number(e.id)===Number(d.state.active_entry_id))),phase:'contestant',next:Date.now()+Number(d.state.contestant_seconds)*1000};render(d)}if(Number(d.state.auto_cycle)&&d.entries.length){if(Date.now()>=cycle.next){if(cycle.phase==='contestant'){cycle.phase='holding';cycle.next=Date.now()+Number(d.state.holding_seconds)*1000;holding(d)}else{cycle.phase='contestant';cycle.index=(cycle.index+1)%d.entries.length;cycle.next=Date.now()+Number(d.state.contestant_seconds)*1000;contestant(d.entries[cycle.index])}}}else if(Number(d.state.state_version)===version&&d.state.screen_type==='scoring')render(d)}catch(e){console.error(e)}}poll();setInterval(poll,2500)})();</script></body></html>
